defmodule Lmx.Notices do
  @moduledoc """
  Writes the license notices every copy of an lmx archive must carry.

  An archive redistributes the Erlang runtime, Elixir, every Hex package the
  release starts and a Rust NIF, and their licenses (MIT, Apache-2.0 section
  4, BSD) require their notices to travel with every copy. The archives used
  to carry none: not even Lemieux's own LICENSE, which sat beside them as a
  release asset that `install.py` and the updater never downloaded.

  `write!/1` puts three files at the archive root, where an installation
  keeps them:

    * `LICENSE` and `NOTICE`, Lemieux's own;
    * `THIRD_PARTY_NOTICES`, assembled here from what this build bundles:
      the Erlang/OTP and Elixir it copied, OpenSSL as linked into `crypto`,
      each Hex package in the release (its `hex_metadata.config` licenses and
      the license, notice and copying files it ships), the Go runtime in
      ExCmd's helper and the NIF's Rust crates.

  What the build cannot read from its inputs is committed under
  `dist/lmx/notices/` and reviewed: `crates.txt` (generated by
  `notices/generate_crates.exs`), the license texts of components that ship
  none (`runtime/`, `hex/`), and one canonical text per SPDX identifier
  (`licenses/`). Assembly refuses to guess. A package with no license file
  and no reviewed supplement, an unknown license name, a missing license
  text, a different ex_ratatui or Cargo.lock than `crates.txt` records, or an
  Erlang/OTP other than the one the runtime section was reviewed for all
  stop the build: a wrong notice is worse than a failed build, because only
  the build is noticed.
  """

  # Erlang/OTP's runtime embeds third-party code whose versions change with
  # OTP. Reviewed against erts/emulator/*/vendor.info and
  # lib/stdlib/uc_spec/vendor.info at the tag below. The move from 29.0.2 to
  # 29.1.1 (2026-10-06) changed none of those manifests — the six files are
  # byte-identical between the tags — so the components and versions below
  # are the ones 29.0.2 was reviewed with.
  @otp_reviewed "29.1.1"
  @otp_components [
    %{
      name: "PCRE2 10.47 (regular expressions, in ERTS)",
      license: "BSD-3-Clause WITH PCRE2-exception",
      file: "runtime/pcre2-LICENCE.txt"
    },
    %{
      name: "AsmJit (the JIT compiler, in ERTS)",
      license: "Zlib",
      file: "runtime/asmjit-LICENSE.txt"
    },
    %{
      name: "zlib 1.3.2 (compression, in ERTS)",
      license: "Zlib",
      file: "runtime/zlib-LICENSE.txt"
    },
    %{
      name: "Zstandard 1.5.7 (compression, in ERTS)",
      license: "BSD-3-Clause OR GPL-2.0-only; used under BSD-3-Clause",
      file: "runtime/zstd-LICENSE.txt"
    },
    %{
      name: "Ryu (float formatting, in ERTS)",
      license: "Apache-2.0 OR BSL-1.0; used under Apache-2.0",
      copyright: "Copyright 2018 Ulf Adams",
      licenses: ["Apache-2.0"]
    },
    %{
      name: "Microsoft STL to_chars (float formatting, in ERTS)",
      license: "Apache-2.0 WITH LLVM-exception AND BSL-1.0",
      copyright: "Copyright 2018 Ulf Adams\nCopyright (c) Microsoft Corporation.",
      licenses: ["Apache-2.0", "LLVM-exception", "BSL-1.0"]
    },
    %{
      name: "Unicode Character Database 17.0.0 (in stdlib)",
      license: "Unicode-3.0",
      copyright: "© 2025 Unicode®, Inc.",
      licenses: ["Unicode-3.0"]
    }
  ]

  # Hex `licenses` entries are free text; these are the spellings in use.
  @spdx %{
    "Apache 2.0" => "Apache-2.0",
    "Apache License 2.0" => "Apache-2.0",
    "Apache-2.0" => "Apache-2.0",
    "BSD 2-Clause" => "BSD-2-Clause",
    "BSD-2-Clause" => "BSD-2-Clause",
    "BSD-3-Clause" => "BSD-3-Clause",
    "ISC" => "ISC",
    "MIT" => "MIT"
  }

  # Licenses whose text names no particular copyright holder: a package that
  # ships no license file is covered by the one canonical text below.
  @holderless ["Apache-2.0"]
  @first_party [:lmx, :lemieux, :lemieux_jev_compaction]
  @elixir_apps [:eex, :elixir, :ex_unit, :iex, :logger, :mix]
  @license_file ~r/^(licen[cs]e|notice|copying|copyright)/i

  @doc """
  Writes `LICENSE`, `NOTICE` and `THIRD_PARTY_NOTICES` to the release root
  and adds them to the files Mix's `:tar` step packs.
  """
  @spec write!(release :: Mix.Release.t()) :: Mix.Release.t()
  def write!(release) do
    deps = Mix.Project.deps_paths()
    root = Map.fetch!(deps, :lemieux)

    for name <- ~w(LICENSE NOTICE),
        do: File.cp!(Path.join(root, name), Path.join(release.path, name))

    linkage = openssl_linkage(release.path)
    :ok = check_linkage!(linkage, System.get_env("LMX_REQUIRE_UPGRADE_PLAN") == "1")

    inventory =
      release.applications
      |> inventory(deps, release.version)
      |> Map.put(:openssl_linkage, linkage)

    File.write!(Path.join(release.path, "THIRD_PARTY_NOTICES"), render(inventory))

    %{release | overlays: Enum.uniq(~w(LICENSE NOTICE THIRD_PARTY_NOTICES) ++ release.overlays)}
  end

  @doc """
  Stops a release-candidate build whose crypto NIF loads OpenSSL from the
  build machine (`linkage` is `{:dynamic, library}`), and only warns in any
  other build. `candidate?` is what release CI and the documented candidate
  builds set `LMX_REQUIRE_UPGRADE_PLAN=1` for.

  Every published archive carries its own OpenSSL: the Linux build copies
  the static OTP `scripts/build-static-otp.sh` makes, and the Erlang/OTP the
  macOS builds copy links it into `crypto` statically as well (measured on a
  29.0.2 macOS release build: `otool -L` lists only libSystem, and
  `crypto:info()` reports `link_type => static`). A dynamic link there means the toolchain changed,
  and the archive would fail to load `crypto` wherever that library is
  missing: Debian slim, a Mac without Homebrew. Nothing else in a release
  run would notice. The macOS runners have Homebrew's OpenSSL, so the smoke
  tests pass on them either way. A local build may link the system's
  OpenSSL and still be useful on that machine, so it gets the warning.
  """
  @spec check_linkage!(
          linkage :: :static | {:dynamic, String.t()} | :unknown,
          candidate? :: boolean()
        ) :: :ok
  def check_linkage!({:dynamic, library}, true) do
    Mix.raise(
      "this release's crypto NIF loads #{library} from the build machine's system, so the " <>
        "archive would not start crypto where that library is missing; build it on an " <>
        "Erlang/OTP that links OpenSSL statically (Lmx.Notices.check_linkage!/2)"
    )
  end

  def check_linkage!({:dynamic, library}, false) do
    Mix.shell().info(
      "warning: this release's crypto NIF loads #{library} from the build machine's " <>
        "system; the archive will not run where that library is missing"
    )
  end

  def check_linkage!(_static_or_unknown, _candidate?), do: :ok

  @doc """
  How the release at `root` carries OpenSSL, read from its crypto NIF's
  dynamic dependencies: `:static` when none of them is an OpenSSL library,
  `{:dynamic, library}` when it loads one from the system, and `:unknown`
  when there is no NIF or no tool to ask (`otool -L` on macOS, `readelf -d`
  on Linux; Windows always answers `:unknown`).

  The notice says what the build did rather than what release builds are
  meant to do: the OTP a build copies decides it, and a local build on an
  Erlang linked against Homebrew's or the distribution's OpenSSL loads it
  dynamically.
  """
  @spec openssl_linkage(root :: Path.t()) :: :static | {:dynamic, String.t()} | :unknown
  def openssl_linkage(root) do
    with [nif | _] <- Path.wildcard(Path.join(root, "lib/crypto-*/priv/lib/crypto.so")),
         {:ok, tool, output} <- describe_binary(nif, :os.type()) do
      case Enum.find(linked_libraries(output, tool), &Regex.match?(~r/^lib(crypto|ssl)\b/, &1)) do
        nil -> :static
        library -> {:dynamic, library}
      end
    else
      _none -> :unknown
    end
  end

  @doc """
  The library names in `otool -L` (macOS) or `readelf -d` (Linux) output for
  one binary.
  """
  @spec linked_libraries(output :: String.t(), tool :: :otool | :readelf) :: [String.t()]
  def linked_libraries(output, :otool) do
    # The first line names the binary; each further line is one library,
    # "\t/usr/lib/libSystem.B.dylib (compatibility version 1.0.0, ...)".
    for line <- output |> String.split("\n", trim: true) |> Enum.drop(1),
        [path | _] = line |> String.trim() |> String.split(" ("),
        do: Path.basename(path)
  end

  def linked_libraries(output, :readelf) do
    # " 0x0000000000000001 (NEEDED)  Shared library: [libcrypto.so.3]"
    for [_line, name] <- Regex.scan(~r/\(NEEDED\)[^\[\n]*\[([^\]\n]+)\]/, output), do: name
  end

  defp describe_binary(path, {:unix, :darwin}), do: run_tool("otool", :otool, ["-L", path])
  defp describe_binary(path, {:unix, _}), do: run_tool("readelf", :readelf, ["-d", path])
  defp describe_binary(_path, _os), do: :error

  defp run_tool(name, tool, args) do
    with path when is_binary(path) <- System.find_executable(name),
         {output, 0} <- System.cmd(path, args, stderr_to_stdout: true) do
      {:ok, tool, output}
    else
      _unavailable -> :error
    end
  end

  @doc """
  Collects what a release bundles, from Mix's application map (each entry has
  `:vsn`, `:path` and `:otp_app?`) and the dependency source directories.
  """
  @spec inventory(
          applications :: %{atom() => keyword()},
          deps :: %{atom() => Path.t()},
          version :: String.t()
        ) :: map()
  def inventory(applications, deps, version) do
    otp_version = otp_version()

    if otp_version != @otp_reviewed,
      do:
        Mix.raise(
          "THIRD_PARTY_NOTICES was reviewed for Erlang/OTP #{@otp_reviewed}, but this build " <>
            "bundles #{otp_version}; review Lmx.Notices' runtime components against that release"
        )

    apps = Enum.sort(applications)

    %{
      version: version,
      target: Lmx.Release.target(),
      otp: %{version: otp_version, erts: to_string(:erlang.system_info(:version))},
      otp_apps: for({app, props} <- apps, props[:otp_app?], do: {app, vsn(props)}),
      elixir: %{version: System.version()},
      elixir_apps: for({app, props} <- apps, app in @elixir_apps, do: {app, vsn(props)}),
      openssl: openssl(),
      packages:
        for(
          {app, props} <- apps,
          not props[:otp_app?],
          app not in @elixir_apps,
          app not in @first_party,
          do: package(app, vsn(props), Map.get(deps, app))
        ),
      crates: crates(apps, deps),
      odu?: Enum.any?(apps, fn {app, _} -> app == :ex_cmd end)
    }
  end

  defp vsn(props), do: props |> Keyword.fetch!(:vsn) |> to_string()

  # Resolved from the project being built rather than from this file at
  # compile time, which would put the build machine's paths into the beam.
  defp notices_dir, do: Path.join(Path.dirname(Mix.Project.project_file()), "notices")

  defp otp_version do
    [:code.root_dir(), "releases", :erlang.system_info(:otp_release), "OTP_VERSION"]
    |> Path.join()
    |> File.read!()
    |> String.trim()
  end

  defp openssl do
    case :crypto.info_lib() do
      [{_name, _number, description} | _] -> to_string(description)
      _ -> "OpenSSL"
    end
  end

  @doc "Describes one bundled Hex package from its source directory."
  @spec package(app :: atom(), version :: String.t(), dir :: Path.t() | nil) :: map()
  def package(app, version, dir) do
    name = Atom.to_string(app)

    unless is_binary(dir) and File.dir?(dir),
      do: Mix.raise("#{name} #{version} is bundled, but its sources are not in deps/")

    metadata = hex_metadata(dir, name)
    licenses = spdx_licenses(metadata, name, version)

    %{
      name: name,
      version: version,
      licenses: licenses,
      link: link(metadata),
      texts: package_texts(license_texts(dir), name, version, licenses)
    }
  end

  defp spdx_licenses(metadata, name, version) do
    case Map.get(metadata, "licenses", []) do
      [] ->
        Mix.raise("#{name} #{version} declares no license")

      licenses ->
        for license <- licenses,
            do:
              Map.get(@spdx, license) ||
                Mix.raise("#{name}: no SPDX identifier for its license #{inspect(license)}")
    end
  end

  # A package's own files; else a reviewed supplement; else nothing, when the
  # canonical license text alone is the notice.
  defp package_texts([_ | _] = texts, _name, _version, _licenses), do: texts

  defp package_texts([], name, version, licenses) do
    supplement = Path.join([notices_dir(), "hex", "#{name}-#{version}.txt"])

    cond do
      File.regular?(supplement) ->
        [{"upstream license, from notices/hex", File.read!(supplement)}]

      Enum.all?(licenses, &(&1 in @holderless)) ->
        []

      true ->
        Mix.raise(
          "#{name} #{version} ships no license text and has no reviewed supplement at " <>
            "notices/hex/#{name}-#{version}.txt; add its upstream license file there"
        )
    end
  end

  defp hex_metadata(dir, name) do
    case :file.consult(String.to_charlist(Path.join(dir, "hex_metadata.config"))) do
      {:ok, terms} ->
        Map.new(terms)

      {:error, reason} ->
        Mix.raise("#{name}: cannot read hex_metadata.config: #{inspect(reason)}")
    end
  end

  defp link(metadata) do
    case Map.get(metadata, "links", []) |> Enum.into(%{}) do
      %{"GitHub" => url} -> url
      links when map_size(links) > 0 -> links |> Map.values() |> Enum.sort() |> hd()
      _ -> nil
    end
  end

  # Top-level license, notice and copying files, and the files of a REUSE
  # style LICENSES/ directory.
  defp license_texts(dir) do
    dir
    |> File.ls!()
    |> Enum.filter(&Regex.match?(@license_file, &1))
    |> Enum.sort()
    |> Enum.flat_map(&license_entry(dir, &1))
  end

  defp license_entry(dir, entry) do
    path = Path.join(dir, entry)

    cond do
      File.regular?(path) -> [{entry, File.read!(path)}]
      File.dir?(path) -> directory_texts(path, entry)
      true -> []
    end
  end

  defp directory_texts(path, entry) do
    for file <- path |> File.ls!() |> Enum.sort(),
        {name, text} <- license_entry(path, file),
        do: {Path.join(entry, name), text}
  end

  defp crates(apps, deps) do
    case List.keyfind(apps, :ex_ratatui, 0) do
      nil ->
        nil

      {:ex_ratatui, props} ->
        text = File.read!(Path.join(notices_dir(), "crates.txt"))
        :ok = check_crates(text, vsn(props), Map.get(deps, :ex_ratatui))
        text
    end
  end

  @doc """
  Checks that `crates.txt` (its text given) describes the bundled ex_ratatui:
  the same version, generated from the same Cargo.lock as the one in `dir`,
  the package's source directory. The crate list is only right for the lock
  file it was generated from.
  """
  @spec check_crates(text :: String.t(), version :: String.t(), dir :: Path.t() | nil) :: :ok
  def check_crates(text, version, dir) do
    recorded = field(text, "ex_ratatui")

    if recorded != version,
      do:
        Mix.raise(
          "notices/crates.txt describes ex_ratatui #{inspect(recorded)}, but this build bundles " <>
            "#{version}; run notices/generate_crates.exs and review the result"
        )

    lock = Path.join([dir || "", "native", "ex_ratatui", "Cargo.lock"])

    unless is_binary(dir) and File.regular?(lock),
      do: Mix.raise("cannot read #{lock} to check notices/crates.txt against it")

    digest = :crypto.hash(:sha256, File.read!(lock)) |> Base.encode16(case: :lower)

    if digest != field(text, "Cargo.lock sha256"),
      do:
        Mix.raise(
          "ex_ratatui's Cargo.lock differs from the one notices/crates.txt was generated " <>
            "from; run notices/generate_crates.exs and review the result"
        )

    :ok
  end

  @doc "Reads a `Name: value` header line from a committed notices file."
  @spec field(text :: String.t(), name :: String.t()) :: String.t() | nil
  def field(text, name) do
    case Regex.run(~r/^#{Regex.escape(name)}: (.+)$/m, text) do
      [_, value] -> String.trim(value)
      nil -> nil
    end
  end

  @doc "Renders `THIRD_PARTY_NOTICES` from `inventory/3`'s result."
  @spec render(inventory :: map()) :: String.t()
  def render(inventory) do
    {packages, _seen} = Enum.map_reduce(inventory.packages, %{}, &package_section/2)

    sections =
      [
        {"Erlang/OTP", otp_section(inventory)},
        {"Elixir", elixir_section(inventory)},
        {"OpenSSL", openssl_section(inventory)},
        {"Hex packages", Enum.join(packages, "\n")},
        inventory.odu? && {"Go runtime in ExCmd's process helper", go_section()},
        inventory.crates && {"Rust crates in the terminal library", inventory.crates},
        {"License texts", license_texts_section(inventory)}
      ]
      |> Enum.filter(& &1)
      |> Enum.with_index(1)

    contents =
      Enum.map_join(sections, "", fn {{title, _}, index} -> "  #{index}. #{title}\n" end)

    body =
      Enum.map_join(sections, "\n", fn {{title, text}, index} ->
        heading = "#{index}. #{title}"
        rule = String.duplicate("=", 78)
        "#{rule}\n#{heading}\n#{rule}\n\n" <> String.trim_trailing(text) <> "\n"
      end)

    """
    THIRD-PARTY NOTICES
    lmx #{inventory.version} (#{inventory.target})

    This archive is lmx, the terminal coding agent built on the Lemieux
    library. Lemieux is licensed under the Apache License, Version 2.0: see
    LICENSE and NOTICE beside this file. The archive also contains the
    Erlang runtime, Elixir and the open-source components below, each under
    its own license. This file reproduces the copyright and license notices
    those licenses ask every copy to carry.

    Contents
    """ <> contents <> "\n" <> body
  end

  defp otp_section(inventory) do
    apps = Enum.map_join(inventory.otp_apps, ", ", fn {app, vsn} -> "#{app} #{vsn}" end)

    components =
      Enum.map_join(@otp_components, "\n", fn component ->
        text =
          case component do
            %{file: file} ->
              String.trim_trailing(File.read!(Path.join(notices_dir(), file))) <> "\n"

            %{copyright: copyright} ->
              copyright <> "\n"
          end

        "--- #{component.name}: #{component.license} ---\n\n" <> text
      end)

    """
    Erlang/OTP #{inventory.otp.version} (ERTS #{inventory.otp.erts})
    License: Apache-2.0
    Copyright Ericsson AB 1996-2026. All Rights Reserved.
    https://www.erlang.org

    Applications in this archive: #{apps}.

    The runtime system also contains the third-party code below. Erlang/OTP's
    complete license files, including those for specifications compiled into
    its applications, are in its source distribution:
    https://github.com/erlang/otp/tree/OTP-#{inventory.otp.version} (LICENSE.txt and LICENSES/).

    #{components}
    """
  end

  defp elixir_section(inventory) do
    apps = Enum.map_join(inventory.elixir_apps, ", ", fn {app, vsn} -> "#{app} #{vsn}" end)

    """
    Elixir #{inventory.elixir.version}
    License: Apache-2.0; its Unicode data: LicenseRef-scancode-unicode
    Copyright (c) 2012 Plataformatec. Copyright (c) 2021 The Elixir Team. All Rights Reserved.
    https://elixir-lang.org

    Applications in this archive: #{apps}.
    """
  end

  defp openssl_section(inventory) do
    """
    #{inventory.openssl}
    License: Apache-2.0
    Copyright (c) 1998-2026 The OpenSSL Project Authors
    Copyright (c) 1995-1998 Eric A. Young, Tim J. Hudson
    All rights reserved.
    https://www.openssl.org

    Erlang/OTP's crypto application uses OpenSSL through its NIF
    (lib/crypto-*/priv/lib).#{openssl_linkage_text(Map.get(inventory, :openssl_linkage, :unknown))}
    """
  end

  defp openssl_linkage_text(:static),
    do: "\nThis build links it into that NIF statically, so the archive contains it."

  defp openssl_linkage_text({:dynamic, library}),
    do: "\nThis build loads it from the system (#{library}); the archive does not contain it."

  # Nothing could be read about this build (Windows has no tool here), so
  # nothing is claimed.
  defp openssl_linkage_text(:unknown), do: ""

  defp go_section do
    """
    ExCmd (MIT, listed under Hex packages) runs commands through odu, a small
    helper program written in Go (lib/ex_cmd-*/priv). The Go runtime and
    standard library compiled into it are licensed as follows.

    """ <> File.read!(Path.join(notices_dir(), "runtime/go-LICENSE.txt"))
  end

  # Identical license files are printed once, then referred to.
  defp package_section(package, seen) do
    {texts, seen} =
      Enum.map_reduce(package.texts, seen, fn {file, text}, seen ->
        key = :crypto.hash(:sha256, String.trim(text))

        case seen do
          %{^key => first} ->
            {"--- #{file}: identical to the text shown for #{first} ---\n", seen}

          _ ->
            {"--- #{file} ---\n\n" <> String.trim_trailing(text) <> "\n",
             Map.put(seen, key, "#{package.name} #{package.version}")}
        end
      end)

    texts =
      if texts == [],
        do: [
          "(This package ships no license file; the #{Enum.join(package.licenses, ", ")} text is in the License texts section.)\n"
        ],
        else: texts

    link = if package.link, do: "\n#{package.link}", else: ""

    section =
      "#{package.name} #{package.version}\nLicense: #{Enum.join(package.licenses, ", ")}#{link}\n\n" <>
        Enum.join(texts, "\n")

    {section, seen}
  end

  defp license_texts_section(inventory) do
    ids =
      ["Apache-2.0", "LicenseRef-scancode-unicode"] ++
        Enum.flat_map(inventory.packages, & &1.licenses) ++
        Enum.flat_map(@otp_components, &Map.get(&1, :licenses, [])) ++
        crate_licenses(inventory.crates)

    ids
    |> Enum.uniq()
    |> Enum.sort()
    |> Enum.map_join("\n", fn id ->
      path = Path.join([notices_dir(), "licenses", id <> ".txt"])

      unless File.regular?(path),
        do: Mix.raise("no license text for #{id}; add notices/licenses/#{id}.txt (SPDX text)")

      "--- #{id} ---\n\n" <> String.trim_trailing(File.read!(path)) <> "\n"
    end)
  end

  defp crate_licenses(nil), do: []

  defp crate_licenses(text) do
    case field(text, "Licenses") do
      nil -> Mix.raise("notices/crates.txt has no Licenses line")
      ids -> String.split(ids, ", ", trim: true)
    end
  end
end
